<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Bookmarks — prototype</title>
<style>
  :root{
    --bg:#f6f7f9; --card:#ffffff; --ink:#1c2430; --muted:#6b7686;
    --line:#e6e9ef; --accent:#2f6fed; --accent-soft:#eaf1ff; --chip:#eef1f6;
    --warn:#8a5a00; --warn-soft:#fff4e0;
  }
  *{box-sizing:border-box}
  body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    background:var(--bg);color:var(--ink);line-height:1.5}
  .wrap{max-width:760px;margin:0 auto;padding:32px 20px 80px}
  h1{font-size:22px;margin:0 0 4px}
  .sub{color:var(--muted);font-size:14px;margin:0 0 24px}

  .topbar{display:flex;align-items:center;gap:8px;margin:0 0 20px;flex-wrap:wrap}
  .topbtn{background:var(--card);border:1px solid var(--line);border-radius:9px;padding:8px 14px;
    font-size:14px;color:#41505f;cursor:pointer}
  .topbtn:hover{border-color:var(--accent);color:var(--accent)}
  .importmsg{font-size:13px;color:var(--muted)}
  .prefspanel{display:none;gap:18px;flex-wrap:wrap;background:var(--card);border:1px solid var(--line);
    border-radius:12px;padding:14px 16px;margin:0 0 20px}
  .prefspanel.show{display:flex}
  .prefspanel .pref{display:flex;flex-direction:column;gap:5px}
  .prefspanel label{font-size:12px;font-weight:600;color:var(--muted);text-transform:uppercase}
  .prefspanel select{border:1px solid var(--line);border-radius:8px;padding:7px 10px;font-size:14px;background:#fff;cursor:pointer}
  body.text-small{font-size:14px}
  body.text-medium{font-size:16px}
  body.text-large{font-size:18px}
  .showmore{display:block;width:100%;background:var(--card);border:1px dashed var(--line);border-radius:10px;
    padding:11px;font-size:14px;color:var(--accent);cursor:pointer;margin-top:4px}
  .showmore:hover{border-color:var(--accent)}

  .composer{background:var(--card);border:1px solid var(--line);border-radius:14px;
    padding:16px;margin-bottom:28px;box-shadow:0 1px 2px rgba(20,30,50,.04)}
  .composer label{display:block;font-size:12px;font-weight:600;color:var(--muted);
    margin:0 0 4px;letter-spacing:.02em;text-transform:uppercase}
  .composer input,.composer textarea{width:100%;border:1px solid var(--line);border-radius:9px;
    padding:10px 12px;font-size:15px;font-family:inherit;background:#fff;color:var(--ink)}
  .composer input:focus,.composer textarea:focus{outline:none;border-color:var(--accent);
    box-shadow:0 0 0 3px var(--accent-soft)}
  .row{margin-bottom:12px}
  .two{display:flex;gap:12px}
  .two>div{flex:1}
  textarea{resize:vertical;min-height:52px}
  .readlater{display:flex;align-items:center;gap:8px;margin:0 0 14px;font-size:14px;color:#37414f;cursor:pointer}
  .readlater input{width:auto}
  .readlater em{color:var(--muted);font-style:normal;font-size:13px}
  .save{background:var(--accent);color:#fff;border:none;border-radius:9px;padding:10px 18px;
    font-size:15px;font-weight:600;cursor:pointer}
  .save:hover{background:#255fd6}

  /* auto-fill preview */
  .preview{display:none;align-items:center;gap:10px;background:#f9fbff;border:1px solid var(--accent-soft);
    border-radius:10px;padding:8px 10px;margin-bottom:12px;font-size:13px;color:var(--muted)}
  .preview.show{display:flex}
  .spinner{width:14px;height:14px;border:2px solid #cdd7ea;border-top-color:var(--accent);
    border-radius:50%;animation:spin .7s linear infinite}
  @keyframes spin{to{transform:rotate(360deg)}}

  .fetchnote{background:var(--warn-soft);color:var(--warn);border:1px solid #f0d9a8;border-radius:10px;
    padding:8px 12px;margin-bottom:12px;font-size:13px}
  .fields{display:none}
  .fields.show{display:block}

  .favicon{width:20px;height:20px;border-radius:4px;flex:0 0 20px;display:inline-flex;
    align-items:center;justify-content:center;color:#fff;font-size:11px;font-weight:700;
    background:var(--accent);overflow:hidden}
  .favicon img{width:100%;height:100%;object-fit:cover}

  .previmg{width:100%;height:120px;border-radius:10px;margin-bottom:12px;
    background-size:cover;background-position:center;border:1px solid var(--line)}
  .item .previmg{height:150px;margin:10px 0 0}

  /* tag input */
  .tagwrap{position:relative}
  .suggest{position:absolute;left:0;right:0;top:100%;background:#fff;border:1px solid var(--line);
    border-radius:9px;box-shadow:0 6px 20px rgba(20,30,50,.12);margin-top:4px;z-index:5;overflow:hidden;display:none}
  .suggest.show{display:block}
  .suggest div{padding:8px 12px;font-size:14px;cursor:pointer}
  .suggest div:hover,.suggest div.active{background:var(--accent-soft)}

  .tabs{display:flex;gap:6px;margin-bottom:14px}
  .tab{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:7px 16px;
    font-size:14px;color:#41505f;cursor:pointer}
  .tab:hover{border-color:var(--accent)}
  .tab.active{background:var(--accent);border-color:var(--accent);color:#fff}
  .tab .tc{opacity:.7;font-size:12px;margin-left:4px}
  .tab.active .tc{opacity:.85}

  .status-pill{display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:3px 10px;
    border-radius:20px;font-weight:600}
  .status-pill.unread{background:#eaf1ff;color:#2f6fed}
  .status-pill.done{background:#e7f6ec;color:#1f8a4c}
  .status-pill.archived-pill{background:#eef1f6;color:#6b7686}
  .toggle-btn.danger{color:#c0392b}
  .toggle-btn.danger:hover{border-color:#c0392b;color:#c0392b}
  .rowactions{display:flex;align-items:center;gap:10px;margin-top:12px;flex-wrap:wrap}
  .toggle-btn{background:none;border:1px solid var(--line);border-radius:8px;padding:5px 12px;
    font-size:13px;color:#41505f;cursor:pointer}
  .toggle-btn:hover{border-color:var(--accent);color:var(--accent)}

  .searchbar{display:flex;align-items:center;gap:8px;background:var(--card);border:1px solid var(--line);
    border-radius:11px;padding:4px 12px;margin-bottom:20px;box-shadow:0 1px 2px rgba(20,30,50,.04)}
  .searchbar:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
  .searchbar .mag{font-size:14px;opacity:.6}
  .searchbar input{flex:1;border:none;outline:none;font-size:15px;padding:8px 0;background:transparent;color:var(--ink)}
  .clearsearch{border:none;background:none;color:var(--muted);font-size:14px;cursor:pointer;display:none}
  .clearsearch.show{display:block}
  mark{background:#fff1a8;color:inherit;border-radius:3px;padding:0 1px}
  .savesearch{border:none;background:none;color:var(--accent);font-size:13px;cursor:pointer;white-space:nowrap;font-weight:600}
  .savesearch:disabled{color:var(--muted);cursor:default;font-weight:400;opacity:.6}
  .savedsearches{display:flex;flex-wrap:wrap;gap:8px;margin:-8px 0 18px}
  .savedsearches:empty{margin:0}
  .savedchip{display:inline-flex;align-items:center;gap:6px;background:#eef4ff;border:1px solid var(--accent-soft);
    border-radius:20px;padding:5px 6px 5px 12px;font-size:13px;color:var(--accent);cursor:pointer}
  .savedchip:hover{background:#e0ebff}
  .savedchip .x{border:none;background:none;color:var(--accent);cursor:pointer;font-size:13px;
    width:18px;height:18px;border-radius:50%;line-height:1}
  .savedchip .x:hover{background:#cfe0ff}
  .savedchip .star{opacity:.8}
  .noteview{font-size:14px;color:#37414f;background:#f9fafc;border:1px solid var(--line);
    border-radius:8px;padding:10px 12px;margin:8px 0 0}
  .noteview ul{margin:4px 0;padding-left:20px}
  .noteview div{margin:2px 0}
  .noteview a{color:var(--accent)}
  .noteview ol{margin:4px 0;padding-left:22px}
  .noteview h3{font-size:16px;margin:8px 0 4px}
  .noteview h4{font-size:15px;margin:8px 0 4px}
  .noteview h5{font-size:14px;margin:8px 0 4px}
  .noteview blockquote{margin:6px 0;padding:4px 12px;border-left:3px solid var(--accent-soft);color:#5b6673}
  .noteview code{background:#eef1f6;border-radius:4px;padding:1px 5px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px}
  .noteview pre{background:#f2f4f8;border-radius:8px;padding:10px 12px;overflow:auto;margin:6px 0}
  .noteview pre code{background:none;padding:0}
  .snapview{font-size:14px;color:#37414f;background:#f9fafc;border:1px solid var(--line);
    border-radius:8px;padding:10px 12px;margin:8px 0 0}
  .snap-row{margin:2px 0}
  .snap-preview{border:1px solid var(--line);border-radius:8px;padding:10px;margin-top:8px;background:#fff}
  .linklike{background:none;border:none;color:var(--accent);cursor:pointer;font-size:14px;padding:0;text-decoration:underline}
  .noteex{font-size:13px;color:#5b6673;background:#f7f8fa;border-left:3px solid var(--line);
    border-radius:6px;padding:6px 10px;margin:8px 0 0;font-style:italic}

  .listhead{display:flex;align-items:baseline;justify-content:space-between;margin:0 0 12px}
  .listhead h2{font-size:15px;margin:0}
  .listhead-right{display:flex;align-items:center;gap:14px}
  .count{color:var(--muted);font-size:13px}
  .sortlabel{font-size:13px;color:var(--muted);display:inline-flex;align-items:center;gap:6px}
  .sortlabel select{border:1px solid var(--line);border-radius:8px;padding:5px 8px;font-size:13px;
    background:#fff;color:var(--ink);cursor:pointer}

  .selectrow{margin:0 0 10px}
  .selectall{display:inline-flex;align-items:center;gap:7px;font-size:13px;color:var(--muted);cursor:pointer}
  .selectall input{width:auto}
  .bulkbar{display:none;align-items:center;gap:10px;flex-wrap:wrap;background:#eef4ff;
    border:1px solid var(--accent-soft);border-radius:11px;padding:10px 14px;margin-bottom:16px}
  .bulkbar.show{display:flex}
  .bulkcount{font-size:14px;font-weight:600;color:var(--accent)}
  .bulkactions{display:flex;gap:6px;flex-wrap:wrap;flex:1}
  .bulkactions button{background:#fff;border:1px solid var(--line);border-radius:8px;padding:6px 12px;
    font-size:13px;color:#41505f;cursor:pointer}
  .bulkactions button:hover{border-color:var(--accent);color:var(--accent)}
  .bulkactions button.danger{color:#c0392b}
  .bulkactions button.danger:hover{border-color:#c0392b}
  .bulkclear{background:none;border:none;color:var(--muted);font-size:13px;cursor:pointer;text-decoration:underline}
  .bulktagpanel{flex-basis:100%;display:none}
  .bulktagpanel.show{display:block}
  .bulktagpanel .pnl{background:#fff;border:1px solid var(--line);border-radius:10px;padding:12px;margin-top:6px}
  .bulktagpanel .pl{font-size:12px;font-weight:600;color:var(--muted);text-transform:uppercase;margin-bottom:6px;display:block}
  .bulktagpanel input{width:100%;border:1px solid var(--line);border-radius:8px;padding:8px 10px;font-size:14px}
  .chips{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}
  .chips .tag{cursor:pointer}
  .chips .tag:hover{background:var(--accent-soft);color:var(--accent)}
  .pnl-actions{display:flex;gap:8px;margin-top:8px}
  .pnl-actions .save{padding:7px 14px;font-size:14px}
  .pnl-actions .cancel{background:none;border:1px solid var(--line);border-radius:8px;padding:7px 14px;font-size:14px;cursor:pointer;color:#41505f}
  .item .selbox{margin-right:2px}
  .item.selected{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}

  .empty{text-align:center;color:var(--muted);padding:48px 16px;border:1px dashed var(--line);
    border-radius:14px;background:#fff}
  .empty .big{font-size:15px;color:var(--ink);margin-bottom:4px}

  .item{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px 18px;
    margin-bottom:12px;box-shadow:0 1px 2px rgba(20,30,50,.04)}
  .item .head{display:flex;gap:10px;align-items:flex-start}
  .item .favicon{width:28px;height:28px;flex:0 0 28px;border-radius:6px;font-size:14px;margin-top:2px}
  .item .title{font-size:16px;font-weight:600;margin:0 0 2px}
  .item .title a{color:var(--ink);text-decoration:none}
  .item .title a:hover{text-decoration:underline}
  .item .url{font-size:12px;color:var(--accent);word-break:break-all;margin:0}
  .item .desc{font-size:14px;color:#37414f;margin:8px 0 10px}
  .tags{display:flex;flex-wrap:wrap;gap:6px}
  .tag{background:var(--chip);color:#41505f;font-size:12px;padding:3px 9px;border-radius:20px}
  .tag.clickable{cursor:pointer}
  .tag.clickable:hover{background:var(--accent-soft);color:var(--accent)}
  .edit-btn{background:none;border:1px solid var(--line);border-radius:8px;padding:5px 12px;
    font-size:13px;color:#41505f;cursor:pointer;margin-top:10px}
  .edit-btn:hover{border-color:var(--accent);color:var(--accent)}
  .just-added{animation:flash 1.4s ease}
  .highlight{box-shadow:0 0 0 3px var(--accent-soft),0 1px 2px rgba(20,30,50,.04);border-color:var(--accent)}
  @keyframes flash{0%{background:var(--accent-soft)}100%{background:var(--card)}}

  .dupbanner{display:none;align-items:center;gap:8px;background:var(--warn-soft);color:var(--warn);
    border:1px solid #f0d9a8;border-radius:10px;padding:10px 12px;margin-bottom:16px;font-size:14px}
  .dupbanner.show{display:flex}

  /* inline editor */
  .editor{background:#f9fbff;border:1px dashed var(--accent);border-radius:10px;padding:12px;margin-top:10px}
  .editor label{display:block;font-size:12px;font-weight:600;color:var(--muted);margin:0 0 4px;text-transform:uppercase}
  .editor input,.editor textarea{width:100%;border:1px solid var(--line);border-radius:8px;padding:8px 10px;
    font-size:14px;font-family:inherit;margin-bottom:8px}
  .editor .save{padding:7px 14px;font-size:14px}
</style>
</head>
